def find_max_1(arr):
    count = 0
    for i in range(len(arr)):
        is_max = True
        for j in range(len(arr)):
            count += 1
            if arr[j] > arr[i]:
                is_max = False
                break
        if is_max:
            return arr[i], count

def find_max_2(arr):
    count = 0
    max_val = arr[0]
    for num in arr:
        count += 1
        if num > max_val:
            max_val = num
    return max_val, count

for n in (10, 100):
    data = list(range(1, n + 1))        # 최댓값이 맨 뒤에 있는 최악의 경우
    print(f'n={n}: 방법1 {find_max_1(data)[1]}번, 방법2 {find_max_2(data)[1]}번')
